'use strict';
const STORE='teztaom-seller-v1', COSTS='lazzat-owner-costs-v1';
const ownerNav=[['overview','Umumiy ko‘rinish','chart'],['branches','Filiallar','pin'],['orders','Buyurtmalar','orders'],['finance','Moliya','wallet'],['dishes','Taomlar tahlili','menu'],['daily','Kun yakuni','calendar'],['team','Jamoa','users'],['settings','Biznes sozlamalari','settings']];
let view='overview', branchFilter='all', period='7', query='', statusFilter='all', returnFocus=null;
let state, expenses=[], dataError='', reportDate=dateInput();
function reload(){try{const raw=localStorage.getItem(STORE);const next=raw?JSON.parse(raw):seed();if(!next.profile||!Array.isArray(next.orders)||!Array.isArray(next.branches)||!Array.isArray(next.staff))throw Error();state=next;if(!raw)localStorage.setItem(STORE,JSON.stringify(next));const costs=JSON.parse(localStorage.getItem(COSTS)||'[]');if(!Array.isArray(costs))throw Error();expenses=costs;dataError='';return true;}catch{dataError='Brauzer ma’lumotlarini o‘qish yoki saqlash imkoni bo‘lmadi. Sahifani yangilang yoki sotuvchi panelidan zaxira nusxani tekshiring.';return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function mutate(fn){if(!reload())throw Error(dataError);const next=structuredClone(state);fn(next);localStorage.setItem(STORE,JSON.stringify(next));state=next;}
const amount=o=>o.items.reduce((s,i)=>s+i.price*i.qty,0);
const branchName=id=>state.branches.find(b=>b.id===id)?.name||'Noma’lum filial';
function since(){return periodBounds().start;}
const selected=o=>canBranch(state,o.branch)&&(branchFilter==='all'||o.branch===branchFilter);
const selectedOrders=()=>scopedOrders();
const selectedCosts=()=>scopedCosts();
function summary(list=selectedOrders()){return financialSummary(list,selectedCosts());}
const button=(label,action,id='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const heading=(title,desc,actions='')=>`<div class="page-title"><div><h1>${title}</h1><p class="subtitle">${desc}</p></div><div class="actions">${actions}</div></div>`;
const emptyOwner=text=>`<div class="empty">${icon('bag')}<br>${text}</div>`;
const labels={new:'Yangi',preparing:'Tayyorlanmoqda',ready:'Tayyor',completed:'Kuryerga berildi',rejected:'Rad etilgan',returned:'Restoranga qaytarilgan'};
const tag=status=>`<span class="tag ${status==='completed'||status==='ready'?'success':status==='rejected'?'danger':'warning'}">${labels[status]||esc(status)}</span>`;
function statsOwner(){const s=summary();return `<div class="stats">${[['Yakunlangan savdo',money(s.sales),'so‘m',`${s.done.length} ta yakunlangan buyurtma`,'wallet'],[s.missing?'Sof foyda (to‘liq emas)':s.estimated?'Sof foyda ≈':'Sof foyda',money(s.net),'so‘m',profitNote(s),'bag'],['Buyurtmalar',selectedOrders().length,'ta','Tanlangan davr va filial bo‘yicha','orders'],['O‘rtacha chek',money(s.done.length?Math.round(s.sales/s.done.length):0),'so‘m','Yakunlangan buyurtmalar bo‘yicha','chart']].map(([label,value,unit,note,i])=>`<article class="stat"><div class="stat-top">${label}<div class="stat-icon">${icon(i)}</div></div><strong>${value} <small>${unit}</small></strong><div class="stat-bottom">${note}</div></article>`).join('')}</div>`;}
function filters(){return `<div class="filters"><select id="branch-filter" aria-label="Filial filtri"><option value="all">Barcha filiallar</option>${scopedBranches(state).map(b=>`<option value="${esc(b.id)}" ${branchFilter===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select><select id="period-filter" aria-label="Davr filtri">${[['1','Bugun'],['week','Bu hafta'],['month','Bu oy'],['7','So‘nggi 7 kun'],['30','So‘nggi 30 kun'],['all','Barcha vaqt']].map(([v,t])=>`<option value="${v}" ${period===v?'selected':''}>${t}</option>`).join('')}</select>${view==='orders'?`<select id="status-filter" aria-label="Buyurtma holati"><option value="all">Barcha holatlar</option>${Object.entries(labels).map(([v,t])=>`<option value="${v}" ${statusFilter===v?'selected':''}>${t}</option>`).join('')}</select><input id="order-search" aria-label="Buyurtma qidirish" placeholder="Buyurtma raqami yoki mijoz" value="${esc(query)}">`:''}${button('CSV hisobot','export')}</div>`;}
function chart(){const range=periodBounds();const count=period==='all'?7:Math.min(31,Math.ceil((range.end-range.start)/86400000));const days=Array.from({length:count},(_,i)=>{const date=new Date();date.setHours(0,0,0,0);date.setDate(date.getDate()-count+1+i);return {date:date.getTime(),label:date.toLocaleDateString('uz-UZ',{day:'2-digit',month:'2-digit'}),value:0};});summary().done.forEach(o=>{const d=new Date(o.completed||o.created);d.setHours(0,0,0,0);const row=days.find(x=>x.date===d.getTime());if(row)row.value+=amount(o);});const max=Math.max(1,...days.map(d=>d.value));return `<div class="panel"><div class="panel-head"><h2>Savdo dinamikasi</h2><span class="tag">${count} kun</span></div><p class="metric-note">Yakunlangan buyurtmalar summasi. ${period==='all'?'Grafikda oxirgi 7 kun ko‘rsatilgan.':''}</p><div class="chart" role="img" aria-label="Kunlik yakunlangan savdo">${days.map(d=>`<div class="bar-wrap" title="${d.label}: ${money(d.value)} so‘m"><div class="bar" style="height:${d.value/max*80}%"></div><span class="bar-label">${d.label}</span></div>`).join('')}</div><div class="chart-summary"><span class="metric-note">${days[0].label} — ${days.at(-1).label}</span><strong>${money(days.reduce((s,d)=>s+d.value,0))} so‘m</strong></div></div>`;}
function orderTable(list){return list.length?`<div class="table-wrap"><table><thead><tr><th>BUYURTMA / MIJOZ</th><th>FILIAL</th><th>VAQT</th><th>SUMMA</th><th>HOLAT</th><th></th></tr></thead><tbody>${list.map(o=>`<tr><td><strong>#${esc(o.id)}</strong><br>${esc(o.customer)}</td><td>${esc(branchName(o.branch))}</td><td>${new Date(o.created).toLocaleString('uz-UZ',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</td><td><strong>${money(amount(o))} so‘m</strong></td><td>${tag(o.status)} ${deliveryBadge(o)}</td><td>${button('Ko‘rish','order',o.id,'small')}</td></tr>`).join('')}</tbody></table></div>`:emptyOwner('Bu filtr bo‘yicha buyurtmalar topilmadi.');}
function overview(){const active=selectedOrders().filter(o=>['new','preparing','ready'].includes(o.status));return `<section class="hero"><div><div class="eyebrow">BIZNES EGASI KABINETI</div><h1>Biznesingiz — bir qarashda</h1><p>${esc(state.profile.name)} filiallari, savdo va jamoani bir joydan kuzating. Bugungi qarorlar uchun aniq raqamlar.</p><span class="tag">2-bosqich · Demo</span></div><div class="hero-icon">${icon('chart')}</div></section>${filters()}${statsOwner()}${comparisons()}${branchComparison()}<div class="two-col">${alertsPanel()}</div><div class="two-col">${chart()}<div class="panel"><h2>Operatsion holat</h2>${[['Filiallar',`${scopedBranches(state).filter(b=>b.active).length} / ${scopedBranches(state).length} faol`,'pin'],['Jarayondagi buyurtmalar',`${active.length} ta`,'clock'],['Faol xodimlar',`${state.staff.filter(s=>s.active&&(isOwner(state)||s.branchId===demoActor(state).branchId)).length} ta`,'users'],['Buyurtma qabul qilish',state.busy?'Band rejimi':'Ochiq','bag']].map(([t,v,i])=>`<div class="activity"><div class="stat-icon">${icon(i)}</div><div><strong>${v}</strong><small>${t}</small></div></div>`).join('')}<p class="metric-note">Hisobotlar shu brauzerdagi demo buyurtmalar asosida hisoblanadi.</p></div></div><div class="panel"><div class="panel-head"><h2>So‘nggi buyurtmalar</h2>${button('Barchasini ko‘rish','nav','orders','small')}</div>${orderTable(selectedOrders().sort((a,b)=>b.created-a.created).slice(0,5))}</div>`;}
function branchesView(){return heading('Filiallar','Har bir filialning holati va natijalari.',isOwner(state)?button('+ Filial qo‘shish','branch','','primary'):'')+filters()+branchComparison()+`<div class="three-col">${scopedBranches(state).filter(b=>branchFilter==='all'||b.id===branchFilter).map(b=>{const orders=selectedOrders().filter(o=>o.branch===b.id);const s=financialSummary(orders,scopedCosts(periodBounds(),b.id));return `<article class="panel branch-card"><span class="tag ${b.active?'success':'warning'}">${b.active?'● Faol':'● Yopiq'}</span><h2>${esc(b.name)}</h2><p class="branch-address">${esc(b.address)}</p><div class="branch-figures"><div>Yakunlangan savdo<strong>${money(s.sales)} <small>so‘m</small></strong></div><div>Buyurtmalar<strong>${orders.length}</strong></div></div><div class="actions">${isOwner(state)?button('Tahrirlash','branch',b.id,'small'):''}${button(b.active?'Yopish':'Ochish','toggle-branch',b.id,'small')}</div></article>`;}).join('')}</div><p class="metric-note">Ish jadvali sotuvchi panelining “Ish vaqti” bo‘limida boshqariladi.</p>`;}
function ordersView(){const q=query.trim().toLocaleLowerCase();const list=selectedOrders().filter(o=>(statusFilter==='all'||statusFilter===o.status)&&`${o.id} ${o.customer}`.toLocaleLowerCase().includes(q)).sort((a,b)=>b.created-a.created);return heading('Barcha buyurtmalar','Filiallar kesimida buyurtmalarni kuzating. Qabul qilish va tayyorlash sotuvchi panelida bajariladi.','<a class="btn primary" href="seller.html">Sotuvchi paneli ↗</a>')+filters()+`<div class="panel" id="order-results">${orderTable(list)}</div>`;}
function financeView(){const s=summary();return heading('Moliya','Yakunlangan demo savdo, komissiya va kiritilgan xarajatlar.',button('+ Xarajat kiritish','expense','','primary'))+filters()+statsOwner()+`<div class="two-col"><div class="panel finance-breakdown"><h2>Daromad va xarajatlar</h2>${[['Yakunlangan savdo',s.sales],['Platforma komissiyasi ('+state.profile.commission+'%)',-s.fee],['Taom tannarxi',-s.food],['Ish haqi',-s.wages],['Boshqa xarajatlar',-s.other],['Sof foyda'+(s.missing?' (to‘liq emas)':s.estimated?' ≈':''),s.net]].map(([t,v])=>`<div class="summary-line"><span>${t}</span><strong>${money(v)} so‘m</strong></div>`).join('')}<p class="metric-note">Sof foyda = savdo − tannarx − komissiya − ish haqi − boshqa xarajatlar. Restoran savdosi kuryerga topshirilganda qayd etiladi; yetkazish holati alohida kuzatiladi. ${profitNote(s)}</p></div><div class="panel"><h2>Xarajatlar jurnali</h2>${selectedCosts().length?selectedCosts().sort((a,b)=>b.date-a.date).map(e=>`<div class="activity"><div style="flex:1"><strong>${esc(e.name)}</strong><small>${e.category==='wage'?'Ish haqi':'Boshqa xarajat'} · ${esc(branchName(e.branch))} · ${new Date(e.date).toLocaleDateString('uz-UZ')}</small><small>${money(e.amount)} so‘m</small></div>${button('O‘chirish','delete-expense',e.id,'small danger')}</div>`).join(''):emptyOwner('Hali xarajat kiritilmagan.')}</div></div>`;}
function teamView(){return heading('Jamoa','Owner — hammasi; menejer — o‘z filiali; sotuvchi — buyurtmalar va menyu. Demo rolni yuqoridan tanlang. Server autentifikatsiyasi hali ulanmagan.',button('+ Xodim qo‘shish','staff','','primary'))+`<div class="panel table-wrap"><table><thead><tr><th>XODIM</th><th>TELEFON</th><th>ROL / FILIAL</th><th>HOLAT</th><th>AMALLAR</th></tr></thead><tbody>${state.staff.map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td>${esc(s.phone)}</td><td><span class="tag">${esc(s.role)}</span><small style="display:block;margin-top:7px">${s.role==='Ega'?'Barcha filiallar':s.branchId?esc(branchName(s.branchId)):'Filial belgilanmagan'}</small></td><td><span class="tag ${s.active?'success':'warning'}">${s.active?'Faol':'O‘chirilgan'}</span></td><td>${s.role==='Ega'?'Asosiy hisob':`<div class="actions">${button('Tahrirlash','staff',s.id,'small')}${button(s.active?'O‘chirish':'Yoqish','toggle-staff',s.id,'small')}</div>`}</td></tr>`).join('')}</tbody></table></div>`;}
const field=(label,name,value='',type='text',attrs='required maxlength="100"')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;
function settingsView(){const p=state.profile;return heading('Biznes sozlamalari','Umumiy profil va demo komissiya. Sotuvchi paneli bilan birgalikda saqlanadi.')+`<form id="business-form" class="panel"><h2>Biznes ma’lumotlari</h2><div class="form-row">${field('Biznes nomi','name',p.name)}${field('Telefon','phone',p.phone,'tel','required pattern="[+0-9 ()-]{9,25}"')}</div><div class="form-row">${field('Elektron pochta','email',p.email,'email')}${field('Demo komissiya (%)','commission',p.commission,'number','required min="0" max="50" step="0.1"')}</div>${field('Manzil','address',p.address,'text','required maxlength="200"')}<div class="notice">Demo: login, qurilmalararo sinxronlash, pul o‘tkazish va kuryer serveri hali ulanmagan. Ma’lumotlar faqat shu brauzer va manzilda saqlanadi.</div><div class="form-error" role="alert"></div><button class="btn primary" type="submit">O‘zgarishlarni saqlash</button></form>`;}
function render(){if(dataError){$('#main').innerHTML=`<div class="notice">${dataError}</div>`;return;}if(!ownerViews(state).includes(view))view=ownerViews(state)[0]||'overview';$('#sidebar').innerHTML=`<a class="brand" href="owner.html" style="text-decoration:none"><div class="brand-mark brand-logo"><img src="assets/lazzat-logo.png" alt="Lazzat" width="36" height="36"></div><div class="brand-text">lazzat<small>BIZNES UCHUN</small></div></a><div class="restaurant"><div class="avatar">${icon('bag')}</div><div><strong>${esc(state.profile.name)}</strong><small>Biznes egasi kabineti</small></div></div><div class="nav-label">BIZNES BOSHQARUVI</div><nav aria-label="Biznes menyusi">${ownerNav.filter(n=>ownerViews(state).includes(n[0])).map(([id,t,i])=>`<button data-action="nav" data-id="${id}" title="${t}" ${view===id?'aria-current="page"':''} class="${view===id?'active':''}"><i class="nav-glyph">${icon(i)}</i><span>${t}</span></button>`).join('')}</nav><div class="sidebar-bottom"><span class="tag">2-bosqich</span><a href="seller.html">← Sotuvchi paneliga o‘tish</a><a href="courier.html">Kuryer paneli ↗</a><p>Lazzat hamkorlar ekotizimi<br>Biznesingiz nazorat ostida.</p></div>`;$('#topbar').innerHTML=`<div class="crumb">Lazzat biznes <span>/</span><strong>${ownerNav.find(n=>n[0]===view)[1]}</strong></div><div class="top-actions">${actorSelector(state)}<a class="btn small" href="seller.html">Sotuvchi paneli ↗</a><div class="account"><div class="avatar">${esc((demoActor(state)?.name||'Biznes egasi').split(' ').map(w=>w[0]).slice(0,2).join(''))}</div><div><strong>${esc(demoActor(state).name||'Biznes egasi')}</strong><small>${esc(demoActor(state).role)} · demo</small></div></div></div>`;$('#main').innerHTML=ownerViews(state).length?({overview,branches:branchesView,orders:ordersView,finance:financeView,dishes:dishesView,daily:dailyView,team:teamView,settings:settingsView})[view]():`<div class="notice">Bu rol uchun biznes paneli yopiq. Buyurtmalar va menyuni sotuvchi panelida boshqaring. Filial belgilanmagan bo‘lsa, owner uni Jamoa bo‘limidan belgilaydi.</div><a class="btn primary" href="seller.html">Sotuvchi paneli</a>`;}
function modal(title,body,form='',id=''){returnFocus=document.activeElement;$('#dialog').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${button('✕','close','','small')}</div>${form?`<form id="${form}" data-id="${esc(id)}">`:''}${body}${form?'<div class="form-error" role="alert"></div><div class="dialog-actions">'+button('Bekor qilish','close')+'<button type="submit" class="btn primary">Saqlash</button></div></form>':''}`;$('#overlay').hidden=false;$('#dialog').focus();$('#dialog input')?.focus();}
function closeModal(){$('#overlay').hidden=true;returnFocus?.focus();}
function branchModal(id){const b=state.branches.find(b=>b.id===id);modal(b?'Filialni tahrirlash':'Yangi filial',field('Filial nomi','name',b?.name||'')+field('Manzil','address',b?.address||'','text','required maxlength="200"')+`<label class="check"><input name="active" type="checkbox" ${!b||b.active?'checked':''}>Filial faol</label>`,'branch-form',id);}
function staffModal(id){if(!isOwner(state))return;const s=state.staff.find(s=>s.id===id);if(s?.role==='Ega')return;modal(s?'Xodimni tahrirlash':'Yangi xodim',field('Ism va familiya','name',s?.name||'')+field('Telefon','phone',s?.phone||'','tel','required pattern="[+0-9 ()-]{9,25}"')+`<div class="field"><label for="f-role">Rol</label><select id="f-role" name="role">${Object.keys(roles).filter(r=>r!=='Ega').map(r=>`<option ${r===s?.role?'selected':''}>${r}</option>`).join('')}</select></div><div class="field"><label for="f-branchId">Filial</label><select required id="f-branchId" name="branchId"><option value="">Filialni tanlang</option>${state.branches.map(b=>`<option value="${esc(b.id)}" ${s?.branchId===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><p class="metric-note">Menejer faqat o‘z filialini ko‘radi. Sotuvchi faqat buyurtmalar va umumiy menyuni boshqaradi. Bu demo filtrlash; xavfsiz kirish uchun server zarur.</p>`,'staff-form',id);}
function expenseModal(){modal('Xarajat kiritish',field('Xarajat nomi','name')+field('Summa (so‘m)','amount','','number','required min="1" max="1000000000" step="1"')+`<div class="field"><label for="f-branch">Filial</label><select id="f-branch" name="branch">${scopedBranches(state).map(b=>`<option value="${esc(b.id)}" ${branchFilter===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div>`+`<div class="field"><label for="f-category">Xarajat turi</label><select id="f-category" name="category"><option value="other">Boshqa xarajat</option><option value="wage">Ish haqi</option></select></div><p class="metric-note">Taom tannarxini bu jurnalga takroran kiritmang; u taomlar tahlilidan hisoblanadi.</p>`+field('Sana','date',dateInput(),'date'),'expense-form');}
function exportReport(){const rows=[['Buyurtma','Mijoz','Filial','Holat','Summa (som)','Komissiya (som)','Yaratilgan vaqt'],...selectedOrders().map(o=>[o.id,o.customer,branchName(o.branch),labels[o.status],amount(o),o.status==='completed'?Math.round(amount(o)*state.profile.commission/100):0,new Date(o.created).toISOString()])];const text='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(/^[=+@\-]/.test(String(v))?"'"+v:v).replace(/"/g,'""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='lazzat-biznes-buyurtmalar.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Tanlangan filial va davr buyurtmalari eksport qilindi.');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;try{if(!ownerActionAllowed(action,id)){toast('Bu amal uchun ruxsat yo‘q.');return;}if(action==='product-cost')costModal(id);if(action==='download-daily')downloadDaily();if(action==='nav'){view=id;query='';render();}if(action==='close')closeModal();if(action==='branch')branchModal(id);if(action==='staff')staffModal(id);if(action==='expense')expenseModal();if(action==='export')exportReport();if(action==='toggle-branch'){mutate(s=>{const b=s.branches.find(b=>b.id===id);if(b)b.active=!b.active;});render();toast('Filial holati saqlandi.');}if(action==='toggle-staff'){mutate(s=>{const p=s.staff.find(p=>p.id===id);if(p&&p.role!=='Ega')p.active=!p.active;});render();toast('Xodim holati saqlandi.');}if(action==='delete-expense'){modal('Xarajatni o‘chirish','<p>Ushbu xarajat jurnal va hisoblangan qoldiqdan olib tashlanadi.</p>','delete-expense-form',id);}if(action==='order'){const o=state.orders.find(o=>o.id===id);modal('Buyurtma #'+esc(o.id),`<p>${esc(o.customer)} · ${esc(o.phone)}</p><p>${esc(branchName(o.branch))} · ${tag(o.status)}</p><div class="table-wrap"><table><tbody>${o.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.qty} × ${money(i.price)}</td><td>${money(i.qty*i.price)} so‘m</td></tr>`).join('')}</tbody></table></div><p><strong>Jami: ${money(amount(o))} so‘m</strong></p><p>${esc(o.note||'Izoh yo‘q')}</p>${deliveryBadge(o)}${o.deliveryAddress?`<p>Yetkazish: ${esc(o.deliveryAddress)}</p>`:''}${o.delivery?`<p>Kuryer: ${esc(state.couriers?.find(c=>c.id===o.delivery.courierId)?.name||'—')}</p>${o.delivery.issue?`<div class="notice">Muammo: ${esc(o.delivery.issue)}</div>`:''}`:''}<a class="btn primary" href="seller.html">Sotuvchi paneliga o‘tish ↗</a>`);}}catch{toast('Saqlab bo‘lmadi. Brauzer xotirasini tekshiring.');}});
document.addEventListener('change',e=>{if(e.target.id==='demo-actor'){chooseActor(e.target.value,state);branchFilter='all';closeModal();reload();render();return;}if(e.target.id==='report-date'){if(/^\d{4}-\d{2}-\d{2}$/.test(e.target.value)){reportDate=e.target.value;render();}return;}if(e.target.id==='branch-filter'){branchFilter=e.target.value;render();}if(e.target.id==='period-filter'){period=e.target.value;render();}if(e.target.id==='status-filter'){statusFilter=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='order-search'){query=e.target.value;const q=query.trim().toLocaleLowerCase();$('#order-results').innerHTML=orderTable(selectedOrders().filter(o=>(statusFilter==='all'||o.status===statusFilter)&&`${o.id} ${o.customer}`.toLocaleLowerCase().includes(q)).sort((a,b)=>b.created-a.created));}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(!form.reportValidity())return;const f=new FormData(form),v=n=>String(f.get(n)||'').trim(),id=form.dataset.id;try{if(!ownerFormAllowed(form,f))throw Error('Bu amal yoki filial uchun ruxsat yo‘q.');if(['branch-form','staff-form','business-form','expense-form'].includes(form.id)&&(!v('name')||v('name').length>100))throw Error('Nomni to‘ldiring (100 belgigacha).');if(form.id==='product-cost-form'){const cost=Number(v('cost'));if(v('cost')===''||!Number.isFinite(cost)||cost<0||cost>100000000)throw Error('Tannarxni to‘g‘ri kiriting.');mutate(s=>{const p=s.products.find(p=>p.id===id);if(!p)throw Error('Taom topilmadi.');p.cost=cost;});}else if(form.id==='branch-form'){if(!v('address'))throw Error('Manzilni to‘ldiring.');mutate(s=>{const b=s.branches.find(b=>b.id===id);const fields={name:v('name'),address:v('address'),active:f.has('active')};if(b)Object.assign(b,fields);else s.branches.push({id:crypto.randomUUID(),...fields,schedule:dayNames.map(name=>({name,open:true,from:'09:00',to:'23:00'}))});});}else if(form.id==='staff-form'){if(!state.branches.some(b=>b.id===v('branchId')))throw Error('Xodim uchun filialni tanlang.');if(!roles[v('role')]||v('role')==='Ega')throw Error('Rolni tanlang.');mutate(s=>{const p=s.staff.find(p=>p.id===id);if(p?.role==='Ega')throw Error('Asosiy hisob o‘zgartirilmaydi.');const fields={name:v('name'),phone:v('phone'),role:v('role'),branchId:v('branchId'),permissions:roles[v('role')]};if(p)Object.assign(p,fields);else s.staff.push({id:crypto.randomUUID(),...fields,active:true});});}else if(form.id==='business-form'){const rate=Number(v('commission'));if(!Number.isFinite(rate)||rate<0||rate>50)throw Error('Komissiya 0–50% oralig‘ida bo‘lsin.');mutate(s=>Object.assign(s.profile,{name:v('name'),phone:v('phone'),email:v('email'),address:v('address'),commission:rate}));}else if(form.id==='expense-form'){if(!reload())throw Error(dataError);const n=Number(v('amount')),date=new Date(v('date')+'T12:00:00').getTime();if(!Number.isFinite(n)||n<=0||n>1e9||!Number.isFinite(date)||!state.branches.some(b=>b.id===v('branch')))throw Error('Summa, sana va filialni tekshiring.');const next=[...expenses,{id:crypto.randomUUID(),name:v('name'),amount:n,date,branch:v('branch'),category:v('category')==='wage'?'wage':'other'}];localStorage.setItem(COSTS,JSON.stringify(next));expenses=next;}else if(form.id==='delete-expense-form'){if(!reload())throw Error(dataError);if(!ownerFormAllowed(form,f))throw Error('Bu filial uchun ruxsat yo‘q.');const next=expenses.filter(e=>e.id!==id);localStorage.setItem(COSTS,JSON.stringify(next));expenses=next;}else return;closeModal();render();toast('O‘zgarishlar saqlandi.');}catch(error){form.querySelector('.form-error').textContent=error.message||'Saqlashda xatolik. Brauzer xotirasini tekshiring.';}});
document.addEventListener('keydown',e=>{if($('#overlay').hidden)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const items=[...$('#dialog').querySelectorAll('button,input,select,a[href]')];const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('storage',e=>{if([STORE,COSTS].includes(e.key)){if(!$('#overlay').hidden||$('#business-form')){toast('Boshqa oynada ma’lumotlar o‘zgardi. Formani tugatib sahifani yangilang.');return;}reload();render();}});
reload();render();
